const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');

const root = path.resolve(__dirname, '..');
const sandbox = { window: {} };
sandbox.globalThis = sandbox.window;
vm.runInNewContext(fs.readFileSync(path.join(root, 'legal/legal-content.js'), 'utf8'), sandbox);
const source = sandbox.window.DUVELA_LEGAL;
const minimal = {
  version: source.version,
  supportedLocales: source.supportedLocales,
  consentTranslations: source.consentTranslations,
  services: source.services,
};
const output = `// Generated by scripts/build-consent-locale-bundle.js.\n` +
  `(function (global) { global.DUVELA_LEGAL = ${JSON.stringify(minimal)}; })(window);\n`;
fs.writeFileSync(path.join(root, 'legal/consent-content.js'), output, 'utf8');
console.log(`[consent-content] ${minimal.supportedLocales.length} locales, ${Buffer.byteLength(output)} bytes`);
